import { IngestPipeline } from "@514labs/moose-lib";

// User Activity Event data model
export interface UserActivity {
  eventId: string;
  eventTs: Date;
  userId: string;
  action: string;
  durationMs: number; // Will default null values to 0 during ingestion
}

// Ingest pipeline with table optimization for query patterns:
// 1. Activity counts per user over date range -> order by userId, eventTs
// 2. Total duration per action type -> include action in ordering
export const UserActivityPipeline = new IngestPipeline<UserActivity>("UserActivity", {
  table: {
    orderByFields: ["userId", "action", "eventTs"]
  },
  stream: true,
  ingestApi: true,
});

